package com.opensocket.aievent.core.iam.authentication.domain;
import java.time.Instant;import java.util.Objects;import java.util.Optional;
public record RootRecoveryGrant(String grantId,String initiatorId,String approverId,String grantHash,Instant issuedAt,Instant expiresAt,Optional<Instant> consumedAt,Status status,long version){public RootRecoveryGrant{grantId=Text.required(grantId,"grantId",128);initiatorId=Text.required(initiatorId,"initiatorId",128);approverId=Text.required(approverId,"approverId",128);if(initiatorId.equals(approverId))throw new IllegalArgumentException("initiator and approver must differ");grantHash=Text.required(grantHash,"grantHash",512);Objects.requireNonNull(issuedAt,"issuedAt");Objects.requireNonNull(expiresAt,"expiresAt");if(!expiresAt.isAfter(issuedAt))throw new IllegalArgumentException("expiresAt must be after issuedAt");consumedAt=consumedAt==null?Optional.empty():consumedAt;Objects.requireNonNull(status,"status");if(version<1)throw new IllegalArgumentException("version must be positive");}public RootRecoveryGrant consume(Instant at){if(status!=Status.ACTIVE||!at.isBefore(expiresAt))throw new AuthenticationDomainException(AuthenticationReasonCode.ROOT_RECOVERY_GRANT_INVALID,"Recovery grant is invalid or expired");return new RootRecoveryGrant(grantId,initiatorId,approverId,grantHash,issuedAt,expiresAt,Optional.of(at),Status.CONSUMED,version+1);}public enum Status{ACTIVE,CONSUMED,REVOKED}}
